# Automatic Taxonomy Builder - runnable demo (JAH-ATK161S-000001)
RANK = 1
SIG = True
TERMS = [('telescope', ['optics', 'stars', 'lens']), ('microscope', ['optics', 'lens', 'cells']), ('novel', ['fiction', 'story']), ('poem', ['verse', 'story']), ('rocket', ['space', 'engine'])]  # (term, keyword-set)
def jaccard(a, b):
    return len(a & b) / len(a | b) if a | b else 0.0
clusters = [{t} for t, _ in TERMS]
kw = {t: set(k) for t, k in TERMS}
while len(clusters) > 2:
    best, bi, bj = -1.0, None, None
    for i in range(len(clusters)):
        for j in range(i+1, len(clusters)):
            ka = set().union(*(kw[t] for t in clusters[i]))
            kb = set().union(*(kw[t] for t in clusters[j]))
            s = jaccard(ka, kb)
            if s > best: best, bi, bj = s, i, j
    if best <= 0: break
    clusters[bi] = clusters[bi] | clusters[bj]
    del clusters[bj]
print("taxonomy (%d top branches):" % len(clusters))
for c in clusters:
    print(" -", ", ".join(sorted(c)))
if RANK >= 2:
    print("terms placed:", sum(len(c) for c in clusters), "/", len(TERMS))
if RANK >= 3:
    sizes = sorted((len(c) for c in clusters), reverse=True)
    print("branch sizes:", sizes)
if SIG:
    print("Signature lineage stamp: JAH-SIG-TAX-" + "JAH-ATK161S-000001")
print("record:", "JAH-ATK161S-000001", "OK")

